const secret = env.get("CHURCHADMIN_CRON_SECRET");

if (!secret || !String(secret).trim()) {
    node.status({ fill: "red", shape: "ring", text: "cron secret missing" });
    node.error("CHURCHADMIN_CRON_SECRET is missing from the Node-RED environment.", msg);
    return null;
}

msg.method = "GET";
msg.url = "https://churchadmins.com/api/followups/process-scheduled?limit=10";
msg.headers = {
    authorization: `Bearer ${String(secret).trim()}`,
    accept: "application/json"
};
msg.payload = undefined;

node.status({ fill: "blue", shape: "dot", text: "checking due follow-ups" });
return msg;

const result = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
const statusCode = Number(msg.statusCode || 0);

// Never pass request or response headers to debug nodes.
delete msg.headers;
delete msg.requestHeaders;
delete msg.responseUrl;

if (statusCode !== 200 || result.ok !== true) {
    const reason = typeof result.error === "string" ? result.error : "Unexpected scheduler response";
    msg.payload = { ok: false, statusCode, error: reason };
    node.status({ fill: "red", shape: "dot", text: `${statusCode || "request"} failed` });
    return [null, msg];
}

const results = Array.isArray(result.results) ? result.results : [];
const blockedPreference = results.filter((item) => item && item.status === "blocked_preference").length;

msg.payload = {
    ok: true,
    checked_at: result.checked_at || null,
    due_count: Number(result.due_count || 0),
    sent: Number(result.sent || 0),
    failed: Number(result.failed || 0),
    blocked_quota: Number(result.blocked_quota || 0),
    blocked_preference: blockedPreference,
    pending: Number(result.pending || 0)
};

node.status({
    fill: Number(result.failed || 0) > 0 ? "yellow" : "green",
    shape: "dot",
    text: `${msg.payload.sent} sent, ${msg.payload.failed} failed`
});
return [msg, null];

delete msg.headers;
delete msg.requestHeaders;
delete msg.responseUrl;
msg.payload = {
    ok: false,
    error: msg.error && msg.error.message ? msg.error.message : "Scheduled follow-up request failed"
};
return msg;
